// #bf7c47 (6a993d6cdaed11dfc1bf7c47) AC4/ד4 «מנהל מגייס רואה דוח בשגיאה: הסבר וכפתור פנייה לתמיכה, אך לא פעולת עיבוד מחדש».
// Кейсы REP-010, REP-011. Роль — business testim (сессия bizt), экран бизнеса — только десктоп (L-20261014-5).
// Данные: отчёты в ошибке QA-CALL1-0411 и QA-C10-2110-D3 (в «לטיפול ידני» — повторно не обрабатываются). Только чтение.
// Кандидат ищется по точному имени (list_candidates); статус отчёта сверяется с ответом API, не зашит.
import { Locator } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { candidateByName, viewById, openReportPage } from './report-view-helpers';
import { listCandidates } from '../candidates/hiring-support';

const HASH = '#bf7c47 · #6a993d6cdaed11dfc1bf7c47';
const ERROR_CANDIDATES = ['QA-CALL1-0411', 'QA-C10-2110-D3'];
const RERUN_CONTROL = /עיבוד מחדש|הפעלה מחדש|הפעלת עיבוד|rerun|reprocess/i;

test.describe(`Менеджер — отчёт в ошибке: объяснение и «פנייה לתמיכה», без перезапуска (${HASH})`, () => {
  for (const name of ERROR_CANDIDATES) {
    test(`отчёт ${name} в ошибке: «שגיאה בהפקת דוח» + «פנייה לתמיכה» (mailto), нет управления перезапуском @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser('bizt');
      await page.setViewportSize({ width: 1440, height: 900 });
      const api = await openWithApi(page, '/candidates');
      const id = await candidateByName(api, name);
      const view = await viewById(api, id);
      expect(view.report?.status, `у ${name} отчёт не в generation_error — данные изменились`).toBe('generation_error');

      await openReportPage(page, id);
      // Источник: AC4 — объяснение и кнопка обращения в поддержку.
      const error = page.getByTestId('report-error');
      await expect(error).toBeVisible();
      await expect(error).toContainText('שגיאה בהפקת דוח');
      const support = error.getByRole('link', { name: 'פנייה לתמיכה' });
      await expect(support).toBeVisible();
      await expect(support).toHaveAttribute('href', /^mailto:/);

      // Источник: AC4/ד4 — действия «перезапуск обработки» у менеджера нет (ни кнопки, ни пункта меню, ни ссылки кроме обращения).
      await expect(page.getByRole('button', { name: RERUN_CONTROL })).toHaveCount(0);
      await expect(page.getByRole('menuitem', { name: RERUN_CONTROL })).toHaveCount(0);
      await expect(page.getByRole('link', { name: RERUN_CONTROL })).toHaveCount(0);
    });
  }

  test(`список кандидатов ?status=generation_error: у строк только «לדוח» и «פנייה לתמיכה» (mailto), без перезапуска @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('bizt');
    await page.setViewportSize({ width: 1440, height: 900 });
    const api = await openWithApi(page, '/candidates?status=generation_error');
    const names = (await listCandidates(api)).map((c) => c.full_name);
    for (const n of ERROR_CANDIDATES) expect(names, `«${n}» есть в list_candidates`).toContain(n);

    const rows = page.getByTestId('candidate-row');
    await expect(rows.first()).toBeVisible({ timeout: 40_000 });
    const rowOf = (n: string): Locator => rows.filter({ has: page.locator('td[data-label="שם"]', { hasText: n }) }).first();

    // Источник: AC4/ד4 — во всех строках отфильтрованного списка нет действия перезапуска обработки.
    const count = await rows.count();
    expect(count, 'в отфильтрованном списке есть строки').toBeGreaterThan(0);
    for (let i = 0; i < count; i++) {
      const row = rows.nth(i);
      await expect(row.getByRole('button', { name: RERUN_CONTROL }), `строка ${i + 1}: кнопка перезапуска`).toHaveCount(0);
      const mail = row.getByTestId('request-reprocessing');
      if (await mail.count()) await expect(mail).toHaveAttribute('href', /^mailto:/);
    }

    // Строки двух QA-отчётов в ошибке: ровно два действия — «לדוח» и mailto-обращение.
    for (const n of ERROR_CANDIDATES) {
      const row = rowOf(n);
      await expect(row, `строка «${n}»`).toBeVisible();
      const report = row.getByTestId('open-candidate-report');
      const mail = row.getByTestId('request-reprocessing');
      await expect(report).toBeVisible();
      await expect(mail).toBeVisible();
      await expect(mail).toHaveAttribute('href', /^mailto:/);
      const actions = report.locator('xpath=..');
      expect(await actions.locator('a, button').count(), `«${n}»: действий в строке`).toBe(2);
    }
  });
});
